<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo; class ReceptionItem extends Model {protected $fillable=['reception_id','product_id','product_category_id','inventory_account','product_name','product_code','unit','quantity','unit_price','selling_price','vat_rate','line_total']; protected $casts=['quantity'=>'decimal:2','unit_price'=>'decimal:2','selling_price'=>'decimal:2','vat_rate'=>'decimal:2','line_total'=>'decimal:2']; public function reception():BelongsTo{return $this->belongsTo(Reception::class);} public function product():BelongsTo{return $this->belongsTo(Product::class);} public function productCategory():BelongsTo{return $this->belongsTo(ProductCategory::class);} }
